// ============================================================================
// CAN_apb: APB4 register wrapper around CAN_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CAN.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CAN.md
// ============================================================================
module CAN_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd
);
  localparam logic [31:0] ID_VALUE = 32'h43410200;

  // ---------------- core ----------------
  logic [5:0]    c_cfg_brp;
  logic [3:0]    c_cfg_tseg1;
  logic [2:0]    c_cfg_tseg2;
  logic [1:0]    c_cfg_sjw;
  logic [28:0]   c_acc_code;
  logic [28:0]   c_acc_mask;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [28:0]   c_tx_id;
  logic          c_tx_ide;
  logic          c_tx_rtr;
  logic [3:0]    c_tx_dlc;
  logic [63:0]   c_tx_data;
  logic          c_tx_abort;
  logic          c_tx_done;
  logic          c_tx_aborted;
  logic          c_rx_valid;
  logic [28:0]   c_rx_id;
  logic          c_rx_ide;
  logic          c_rx_rtr;
  logic [3:0]    c_rx_dlc;
  logic [63:0]   c_rx_data;
  logic          c_arb_lost;
  logic          c_err_bit;
  logic          c_err_stuff;
  logic          c_err_crc;
  logic          c_err_form;
  logic          c_err_ack;
  logic [8:0]    c_tec;
  logic [7:0]    c_rec;
  logic          c_err_passive;
  logic          c_bus_off;
  CAN_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .cfg_brp(c_cfg_brp),
    .cfg_tseg1(c_cfg_tseg1),
    .cfg_tseg2(c_cfg_tseg2),
    .cfg_sjw(c_cfg_sjw),
    .acc_code(c_acc_code),
    .acc_mask(c_acc_mask),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_id(c_tx_id),
    .tx_ide(c_tx_ide),
    .tx_rtr(c_tx_rtr),
    .tx_dlc(c_tx_dlc),
    .tx_data(c_tx_data),
    .tx_abort(c_tx_abort),
    .tx_done(c_tx_done),
    .tx_aborted(c_tx_aborted),
    .rx_valid(c_rx_valid),
    .rx_id(c_rx_id),
    .rx_ide(c_rx_ide),
    .rx_rtr(c_rx_rtr),
    .rx_dlc(c_rx_dlc),
    .rx_data(c_rx_data),
    .arb_lost(c_arb_lost),
    .err_bit(c_err_bit),
    .err_stuff(c_err_stuff),
    .err_crc(c_err_crc),
    .err_form(c_err_form),
    .err_ack(c_err_ack),
    .tec(c_tec),
    .rec(c_rec),
    .err_passive(c_err_passive),
    .bus_off(c_bus_off)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [17:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd18) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [13:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [14:0] r_BTR;   // 12'h014 BTR
  logic [28:0] r_ACC_CODE;   // 12'h018 ACC_CODE
  logic [28:0] r_ACC_MASK;   // 12'h01C ACC_MASK
  logic [31:0] h_TX0;   // 12'h020 TX0 holding register
  logic [31:0] h_TX1;   // 12'h024 TX1 holding register
  logic [30:0] h_TX2;   // 12'h028 TX2 holding register
  logic [3:0] h_TX3;   // 12'h02C TX3 holding register
  logic [0:0] p_CMD;   // 12'h030 CMD (pulses)
  logic [31:0] h_RX0;   // 12'h034 RX0 holding register
  logic [31:0] h_RX1;   // 12'h038 RX1 holding register
  logic [30:0] h_RX2;   // 12'h03C RX2 holding register
  logic [3:0] h_RX3;   // 12'h040 RX3 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_BTR <= 15'h2941;
      r_ACC_CODE <= 29'h0;
      r_ACC_MASK <= 29'h0;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_TX2 <= '0;
      h_TX3 <= '0;
      p_CMD <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_RX2 <= '0;
      h_RX3 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[13:0] & wmask[13:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[13:0]) | (PWDATA[13:0] & wmask[13:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_BTR <= (r_BTR & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[6]) r_ACC_CODE <= (r_ACC_CODE & ~wmask[28:0]) | (PWDATA[28:0] & wmask[28:0]);
      if (wr && hit[7]) r_ACC_MASK <= (r_ACC_MASK & ~wmask[28:0]) | (PWDATA[28:0] & wmask[28:0]);
      p_CMD <= (wr && hit[12]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[8] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10] && !full_TX) h_TX2 <= (h_TX2 & ~wmask[30:0]) | (PWDATA[30:0] & wmask[30:0]);
      if (wr && hit[11] && !full_TX) h_TX3 <= (h_TX3 & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[11] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[16]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        h_RX2[28:0] <= c_rx_id[28:0];
        h_RX2[29:29] <= c_rx_ide;
        h_RX2[30:30] <= c_rx_rtr;
        h_RX3[3:0] <= c_rx_dlc[3:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[16]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_brp = r_BTR[5:0];
  assign c_cfg_tseg1 = r_BTR[9:6];
  assign c_cfg_tseg2 = r_BTR[12:10];
  assign c_cfg_sjw = r_BTR[14:13];
  assign c_acc_code = r_ACC_CODE[28:0];
  assign c_acc_mask = r_ACC_MASK[28:0];
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_data[63:32] = h_TX1[31:0];
  assign c_tx_id[28:0] = h_TX2[28:0];
  assign c_tx_ide = h_TX2[29:29];
  assign c_tx_rtr = h_TX2[30:30];
  assign c_tx_dlc[3:0] = h_TX3[3:0];
  assign c_tx_abort = p_CMD;
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_tx_aborted;
    irq_set[2] = c_arb_lost;
    irq_set[3] = c_err_bit;
    irq_set[4] = c_err_stuff;
    irq_set[5] = c_err_crc;
    irq_set[6] = c_err_form;
    irq_set[7] = c_err_ack;
    irq_set[8] = c_err_passive;
    irq_set[9] = c_bus_off;
    irq_set[10] = full_TX & c_tx_ready;
    irq_set[11] = wr & (hit[8] | hit[9] | hit[10] | hit[11]) & full_TX;
    irq_set[12] = c_rx_valid & (~avail_RX | (rd & hit[16]));
    irq_set[13] = c_rx_valid & avail_RX & ~(rd & hit[16]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_BTR);
      10'd6: rdata = 32'(r_ACC_CODE);
      10'd7: rdata = 32'(r_ACC_MASK);
      10'd8: rdata = 32'(h_TX0);
      10'd9: rdata = 32'(h_TX1);
      10'd10: rdata = 32'(h_TX2);
      10'd11: rdata = 32'(h_TX3);
      10'd13: rdata = 32'(h_RX0);
      10'd14: rdata = 32'(h_RX1);
      10'd15: rdata = 32'(h_RX2);
      10'd16: rdata = 32'(h_RX3);
      10'd17: rdata = 32'({c_bus_off, c_err_passive, c_rec, c_tec});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
